import{_ as o,o as t,c as l,a2 as i}from"./chunks/framework.DGk0zlJw.js";const s=JSON.parse('{"title":"装机验收补充清单（todo 未勾 18 项 · 2026-10-27）","description":"","frontmatter":{},"headers":[],"relativePath":"review/2026-10-27-manual-acceptance-supplement.md","filePath":"review/2026-10-27-manual-acceptance-supplement.md"}'),e={name:"review/2026-10-27-manual-acceptance-supplement.md"};function d(r,a,h,n,c,m){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="装机验收补充清单-todo-未勾-18-项-·-2026-10-27" tabindex="-1">装机验收补充清单（todo 未勾 18 项 · 2026-10-27） <a class="header-anchor" href="#装机验收补充清单-todo-未勾-18-项-·-2026-10-27" aria-label="Permalink to &quot;装机验收补充清单（todo 未勾 18 项 · 2026-10-27）&quot;">​</a></h1><blockquote><p>源头：<code>todo.md</code> 截至 2026-10-27 的 18 条未勾项。其中 <strong>16 条为真机交互项</strong>（本地 Linux 无 Windows 显示栈/托盘/多屏，自动化半已有 CI 场景或单测证据，余下真人装机半在此逐条给出步骤），<strong>2 条为用户材料项</strong>（缺凭据/文档，非代码可推进）。 与《装机验收执行清单 71 条》（<code>docs/acceptance-checklist.md</code>，2026-10-12）的关系：本清单只补 18 条未勾项的剩余半，通用准备（E0 装包 / E1 日志 / E2 回执 / C-DPI 等）与重叠条目直接引用该清单编号，不重复展开。 回执口径同 E2：每条记「通过 / 失败+现象+截图或日志行」；通过即在 <code>todo.md</code> 对应行注日期勾账；失败只记现象不自修。观感项「改了未验不算完成」。</p></blockquote><hr><h2 id="a-真机交互项-16-条" tabindex="-1">A. 真机交互项（16 条） <a class="header-anchor" href="#a-真机交互项-16-条" aria-label="Permalink to &quot;A. 真机交互项（16 条）&quot;">​</a></h2><h3 id="a-1-跨-dpi-拖动不错乱-todo-md-45" tabindex="-1">A-1｜跨 DPI 拖动不错乱（todo.md:45） <a class="header-anchor" href="#a-1-跨-dpi-拖动不错乱-todo-md-45" aria-label="Permalink to &quot;A-1｜跨 DPI 拖动不错乱（todo.md:45）&quot;">​</a></h3><ul><li>前置：C-DPI（两块缩放不同的屏，如 100% + 200%）。已有证据：场景 R/R3（38750239155）覆盖重启位置与普通拖动。</li><li>步骤：① 面板贴屏 A，逐个拖 tile 到屏 B 松手；② 面板整体跨屏拖动；③ 拖动过程中往复跨屏来回；④ 拖完重启应用。</li><li>通过标准：tile 落点与松手位置一致（无跳变/爬行），文字不裁不糊，重启后位置在原屏原位；拖动中无闪烁（WM_DPICHANGED 与拖动互抢已在代码面修）。</li><li>参考：71 条清单 2.13 / 2.15。</li></ul><h3 id="a-2-url-端到端打开-todo-md-58" tabindex="-1">A-2｜URL 端到端打开（todo.md:58） <a class="header-anchor" href="#a-2-url-端到端打开-todo-md-58" aria-label="Permalink to &quot;A-2｜URL 端到端打开（todo.md:58）&quot;">​</a></h3><ul><li>前置：任一连接配置了控制台/详情 URL（如 http 连接、GitHub 仓库链接）。</li><li>步骤：① tile 右键/详情窗点「打开控制台」类链接；② 观察默认浏览器。</li><li>通过标准：默认浏览器打开且地址与配置一致（拼接无重复斜杠/无未替换模板占位符）；无 URL 时不渲染可点项。</li><li>已有证据：TemplateRendererTests 覆盖拼接纯函数半。</li></ul><h3 id="a-3-toast-发送-点击-激活路由-todo-md-63" tabindex="-1">A-3｜Toast 发送/点击/激活路由（todo.md:63） <a class="header-anchor" href="#a-3-toast-发送-点击-激活路由-todo-md-63" aria-label="Permalink to &quot;A-3｜Toast 发送/点击/激活路由（todo.md:63）&quot;">​</a></h3><ul><li>前置：Windows 通知中心可用；通知规则已启用（71 条清单 2.9）。已有证据：AUMID 自愈场景 F5t（38494525200）。</li><li>步骤：① 制造告警（断网 C-DISCONNECT 或 mock 服务器置 error）等 Toast 弹出；② 点击 Toast 正文；③ 点掉后从通知中心历史再点一次。</li><li>通过标准：Toast 弹出（含图标与标题）；点击后应用置前并直达对应 tile 的详情窗（路由正确，非只激活主窗）；通知中心历史条目点击同样路由。</li></ul><h3 id="a-4-托盘图标颜色-刷新周期-todo-md-66" tabindex="-1">A-4｜托盘图标颜色/刷新周期（todo.md:66） <a class="header-anchor" href="#a-4-托盘图标颜色-刷新周期-todo-md-66" aria-label="Permalink to &quot;A-4｜托盘图标颜色/刷新周期（todo.md:66）&quot;">​</a></h3><ul><li>前置：E1 日志。已有证据：tile 更新场景 G7a（38%→95%，75s 内）。</li><li>步骤：① 健康态观察托盘图标颜色；② mock 置 error/恢复健康，掐表观察托盘图标变色时延；③ 对照设置的刷新周期。</li><li>通过标准：托盘图标颜色与档位一致（绿/黄/红/离线灰），变色时延 ≤ 刷新周期 + 一次轮询，无长期滞留旧色。</li></ul><h3 id="a-5-悬浮-tile-点击穿透观感-todo-md-71" tabindex="-1">A-5｜悬浮 tile 点击穿透观感（todo.md:71） <a class="header-anchor" href="#a-5-悬浮-tile-点击穿透观感-todo-md-71" aria-label="Permalink to &quot;A-5｜悬浮 tile 点击穿透观感（todo.md:71）&quot;">​</a></h3><ul><li>前置：已钉至少一个 tile 且开启悬浮（0341abc 已加 WS_EX_TRANSPARENT，不用全局钩子）。</li><li>步骤：① 在悬浮 tile 的空白边缘/间隙处点击/框选，观察下层窗口；② 点 tile 内容区（数据/灯位）。</li><li>通过标准：空白处点击落到下层窗口（穿透成立，不挡操作）；内容区点击仍由 tile 响应（打开详情）；悬浮窗不抢焦点、不出现在 Alt-Tab。</li></ul><h3 id="a-6-多显示器越界回收-todo-md-77" tabindex="-1">A-6｜多显示器越界回收（todo.md:77） <a class="header-anchor" href="#a-6-多显示器越界回收-todo-md-77" aria-label="Permalink to &quot;A-6｜多显示器越界回收（todo.md:77）&quot;">​</a></h3><ul><li>前置：C-DPI 双屏，tile 拖到副屏。</li><li>步骤：① 设置里禁用副屏（或拔线）→ 观察 tile；② 重新启用；③ 改低主屏分辨率再恢复。</li><li>通过标准：副屏消失后 tile 全部回到可见主屏内（无「藏在屏外」的不可达 tile，重启后同样）；分辨率变化同理；pins.json 不被写坏。</li></ul><h3 id="a-7-rfc-§6-2-7-四项铁律-todo-md-80" tabindex="-1">A-7｜RFC §6.2.7 四项铁律（todo.md:80） <a class="header-anchor" href="#a-7-rfc-§6-2-7-四项铁律-todo-md-80" aria-label="Permalink to &quot;A-7｜RFC §6.2.7 四项铁律（todo.md:80）&quot;">​</a></h3><ul><li>步骤（逐项）：① 点 tile → 打开该组件详情（钻取成立）；② 制造告警 → L0 面板本体<strong>不</strong>弹 Toast/不出声，只有状态灯变色（Toast 归通知引擎，即 A-3 那条链）；③ 检查 L0/tile 面与悬浮 tile 的可点项——只有零风险「打开链接」类，无 Deploy/Restart 等需确认动作（它们只在 L2/L3）；④ 拖动/刷新/告警全程不抢焦点，Alt-Tab 列表与任务栏无 Beacon 条目（托盘图标除外）。</li><li>通过标准：四项全过；任何一项违例记现象+截图。</li></ul><h3 id="a-8-托盘图标同步改色-todo-md-81" tabindex="-1">A-8｜托盘图标同步改色（todo.md:81） <a class="header-anchor" href="#a-8-托盘图标同步改色-todo-md-81" aria-label="Permalink to &quot;A-8｜托盘图标同步改色（todo.md:81）&quot;">​</a></h3><ul><li>已有证据：tile/胶囊改色 G4/G5（38953986133）。</li><li>步骤：① 设置里给某 tile 配 colorOverride → 看托盘图标；② 重置颜色 → 再看；③ 改全局档位色 → 再看。</li><li>通过标准：托盘图标跟随同一配色源变化（优先级 Widget &gt; 档位 &gt; 默认），与 tile/胶囊同刻变色，重置回默认。</li></ul><h3 id="a-9-动效观感与强度裁量-todo-md-85" tabindex="-1">A-9｜动效观感与强度裁量（todo.md:85） <a class="header-anchor" href="#a-9-动效观感与强度裁量-todo-md-85" aria-label="Permalink to &quot;A-9｜动效观感与强度裁量（todo.md:85）&quot;">​</a></h3><ul><li>已有证据：档位/强度差分 G6/G7b/G7c/V2。</li><li>步骤：① 默认 reduced 档日常观察（色变过渡 + Critical 脉冲）；② 切 full 档（呼吸灯常驻）对比；③ 强度 0.5 / 1.0 / 2.0 三档对比；④ off 档确认完全静止。</li><li>通过标准：各档行为与 RFC §6.2.8 表一致；观感无抖动/撕裂/掉帧；full 档动画不 CPU/GPU 爆表（任务管理器粗看）；真人裁量观感「可接受」即过，不满意记具体现象。</li></ul><h3 id="a-10-全流程录屏归档-todo-md-88" tabindex="-1">A-10｜全流程录屏归档（todo.md:88） <a class="header-anchor" href="#a-10-全流程录屏归档-todo-md-88" aria-label="Permalink to &quot;A-10｜全流程录屏归档（todo.md:88）&quot;">​</a></h3><ul><li>步骤：一段连续录屏走完：添加连接 → 钉 tile → 组件中心配展示样式（含恢复传统渲染）→ 快捷面板 → 详情窗 → 执行一个动作 → 通知 → 重启恢复位置。</li><li>通过标准：全流程无阻断/崩溃/明显错位；录屏归档 <code>docs/</code>（E2 口径）。</li></ul><h3 id="a-11-b-803-干净-win11-虚拟机-todo-md-89" tabindex="-1">A-11｜B-803 干净 Win11 虚拟机（todo.md:89） <a class="header-anchor" href="#a-11-b-803-干净-win11-虚拟机-todo-md-89" aria-label="Permalink to &quot;A-11｜B-803 干净 Win11 虚拟机（todo.md:89）&quot;">​</a></h3><ul><li>步骤：干净 Windows 11 VM（无开发环境）→ E0 装 nightly 包 → 首启 → 走 A-10 的精简版（连接一条 + 钉一个 tile + 一次详情）。</li><li>通过标准：无缺运行时报错（自包含成立）、首启引导可用、核心链路通；失败附 VM 截图。</li></ul><h3 id="a-12-登录会话自启调度-todo-md-102" tabindex="-1">A-12｜登录会话自启调度（todo.md:102） <a class="header-anchor" href="#a-12-登录会话自启调度-todo-md-102" aria-label="Permalink to &quot;A-12｜登录会话自启调度（todo.md:102）&quot;">​</a></h3><ul><li>已有证据：Run 注册表值 + ShellExecute 场景 M3（38761946476）。</li><li>步骤：① 设置启用开机自启 → 注销重登；② 重启整机一次；③ 关闭自启 → 再注销重登。</li><li>通过标准：启用后登录即见托盘图标与恢复的 tile（用户会话内、非提权）；关闭后不再自启。</li></ul><h3 id="a-13-长稳浸泡-todo-md-103" tabindex="-1">A-13｜长稳浸泡（todo.md:103） <a class="header-anchor" href="#a-13-长稳浸泡-todo-md-103" aria-label="Permalink to &quot;A-13｜长稳浸泡（todo.md:103）&quot;">​</a></h3><ul><li>已有证据：托盘驻留/15 分钟浸泡 E2/E3/AD（39057049259）。</li><li>步骤：真机连续挂 ≥4 小时（含至少一次断网恢复），任务管理器每半小时看一次内存/CPU。</li><li>通过标准：无崩溃/无窗体错位；内存无持续上涨（稳态波动可）；日志无周期性报错；胶囊/悬浮 tile 观感全程正常。</li></ul><h3 id="a-14-动作端到端执行-todo-md-210" tabindex="-1">A-14｜动作端到端执行（todo.md:210） <a class="header-anchor" href="#a-14-动作端到端执行-todo-md-210" aria-label="Permalink to &quot;A-14｜动作端到端执行（todo.md:210）&quot;">​</a></h3><ul><li>已有证据：本机日志 356 次刷新全 ok + Actions 27 测试；场景 AF Windows CI 实跑（run 40903469089，cf43001）——步骤①命令半、③确认弹窗、④失败反馈已代验：cmd.exe 真子进程写 marker 文件落地、确认弹窗取消不执行与确认执行双径断言、坏命令反馈「无法启动命令」不静默。</li><li>步骤：① 配置一个「打开 URL」动作与一个本地命令动作（如记事本）；② 从详情窗/tile 可点区执行 URL 半；③ 走一次需确认动作的确认弹窗；④ 断网时执行一个远端动作。</li><li>通过标准：URL 动作真开浏览器（余唯一手动项，归 A-2 口径）；命令动作真拉起进程；确认弹窗取消则不执行；失败路径有反馈不静默。</li></ul><h3 id="a-15-显示器切换-dpi-变化重启恢复-todo-md-212" tabindex="-1">A-15｜显示器切换/DPI 变化重启恢复（todo.md:212） <a class="header-anchor" href="#a-15-显示器切换-dpi-变化重启恢复-todo-md-212" aria-label="Permalink to &quot;A-15｜显示器切换/DPI 变化重启恢复（todo.md:212）&quot;">​</a></h3><ul><li>已有证据：两轮实机 pins.json 恢复记录（monitor/anchor/offset/collapsed）。</li><li>步骤：① 单屏挂机下改缩放 100%→150%→100%，各重启一次；② 接副屏/拔副屏各重启一次。</li><li>通过标准：每次重启 tile 全部落在可见屏内、吸附边正确、尺寸随 DPI 正确缩放（不裁字不缩成点）。</li></ul><h3 id="a-16-展示模板裁切观感复核-todo-md-139-余项-f9a9aac-代码半已落" tabindex="-1">A-16｜展示模板裁切观感复核（todo.md:139 余项，f9a9aac 代码半已落） <a class="header-anchor" href="#a-16-展示模板裁切观感复核-todo-md-139-余项-f9a9aac-代码半已落" aria-label="Permalink to &quot;A-16｜展示模板裁切观感复核（todo.md:139 余项，f9a9aac 代码半已落）&quot;">​</a></h3><ul><li>前置：≥1 条产额类连接（智谱/方舟等 8 家任一）。</li><li>步骤：① 组件中心分别应用横条/圆环/数字卡/水位/状态行五模板 × tile 尺寸档（小/中/大）逐组合观察；② 真实数据从 0%→满量程变化时观察；③ 数据缺失态（断网）观察「等待数据」占位；④ 样式优先级（2026-10-30 决策第 18 项补）：选一个已设实例样式的组件，改全局 progressStyle，确认该实例展示不受全局影响（实例样式优先）；再把该组件恢复传统渲染，确认全局 progressStyle 生效；重启后复查两态仍各归其位。</li><li>通过标准：所有组合不裁切不溢出（tile 高度自动抬升到模板最小高）；0% 与「等待数据」可区分；优先级符合既定规则——实例展示样式控制该实例、全局 progressStyle 控传统渲染、恢复传统后即受全局控制；改观感不满意记具体模板+档位+截图。</li></ul><h3 id="a-17-ui-升级观感验收-2026-10-29-brimdeck-对照批-5140fe9-9603f85-ci-绿" tabindex="-1">A-17｜UI 升级观感验收（2026-10-29 BrimDeck 对照批，5140fe9+9603f85，ci 绿） <a class="header-anchor" href="#a-17-ui-升级观感验收-2026-10-29-brimdeck-对照批-5140fe9-9603f85-ci-绿" aria-label="Permalink to &quot;A-17｜UI 升级观感验收（2026-10-29 BrimDeck 对照批，5140fe9+9603f85，ci 绿）&quot;">​</a></h3><ul><li>前置：nightly ≥2026-10-30 构建（含胶囊环/悬停预览与面板卡片栅格）。</li><li>步骤：① 开胶囊（config <code>showCapsule:true</code>）看收起态：健康环+光晕灯+计数三件并置、高 32 不裁；② 鼠标悬停胶囊看各数据源摘要展开（出窗收起、拖动时收起）；③ 状态变差（断 mock 或注入 error）看灯/晕/环换色与闪烁动效，动效档 off 时应全瞬时；④ 开快速面板看 OVERVIEW 卡片栅格（图标+环+计数+来源名、点击过滤、激活卡强调色）；⑤ 深浅主题各过一遍。</li><li>通过标准：观感达到「不丑于 BrimDeck 截图」主观线；环弧与计数一致；两主题文字均可读；不满意处记面+主题+截图。</li></ul><hr><h2 id="b-用户材料项-2-条-非代码可推进" tabindex="-1">B. 用户材料项（2 条，非代码可推进） <a class="header-anchor" href="#b-用户材料项-2-条-非代码可推进" aria-label="Permalink to &quot;B. 用户材料项（2 条，非代码可推进）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>todo 行</th><th>缺的材料</th><th>用户给出后要做什么</th></tr></thead><tbody><tr><td>:97</td><td>目标厂商名称、私有 API 文档/端点、真实认证字段与可用凭据</td><td>按材料写 Provider（Jenkins 标准 API 先例已落位 2026-10-11，照抄接入面）</td></tr><tr><td>:105</td><td>可用的 GitHub PAT 与目标仓库（或明确授权的真实仓库）</td><td>建 C-GH 连接走真实 PR/Actions 数据链（现有 mock/匿名证据不能替代）</td></tr></tbody></table><hr><h2 id="覆盖对照-防漏" tabindex="-1">覆盖对照（防漏） <a class="header-anchor" href="#覆盖对照-防漏" aria-label="Permalink to &quot;覆盖对照（防漏）&quot;">​</a></h2><p>16 真机项 = todo.md 未勾行 45/58/63/66/71/77/80/81/85/88/89/102/103/139/210/212；2 材料项 = 97/105。合计 18 = todo.md 当前全部未勾项（2026-10-27 核对）。</p>',44)])])}const b=o(e,[["render",d]]);export{s as __pageData,b as default};
